function prepare({ event, collectionId, parentDocumentId }) {
  if (
    !event ||
    event.object_kind !== "release" ||
    !["create", "update", "delete"].includes(event.action)
  )
    throw Error("Invalid GitLab release event");
  if (event.action !== "create") return { publish: false, body: {} };
  if (
    typeof event.name !== "string" ||
    !event.name.trim() ||
    typeof event.url !== "string" ||
    !/^https?:\/\/\S+$/i.test(event.url)
  )
    throw Error("Invalid GitLab release");
  if (typeof collectionId !== "string" || !collectionId.trim() || collectionId.startsWith("YOUR_"))
    throw Error("Configure the Outline collection ID");
  if (typeof parentDocumentId !== "string" || parentDocumentId.startsWith("YOUR_"))
    throw Error("Configure or clear the parent document ID");
  const description = event.description == null ? "" : event.description;
  if (typeof description !== "string") throw Error("Invalid release description");
  return {
    publish: true,
    body: {
      collectionId,
      ...(parentDocumentId.trim() ? { parentDocumentId: parentDocumentId.trim() } : {}),
      publish: true,
      title: "Release " + event.name,
      text: description + "\n\n\\\n[More info](" + event.url + ")",
    },
  };
}

return $input.all().flatMap((x, i) => {
  const p = prepare({
    event: x.json.body,
    collectionId: "YOUR_COLLECTION_ID",
    parentDocumentId: "",
  });
  return p.publish ? [{ json: p, pairedItem: { item: i } }] : [];
});

function confirm({ body, statusCode }) {
  if (
    statusCode < 200 ||
    statusCode >= 300 ||
    !body ||
    body.ok === false ||
    typeof body.data?.id !== "string" ||
    !body.data.id
  )
    throw Error("Outline document was not confirmed; inspect before retry");
  return { document: body.data };
}

return $input.all().map((x, i) => ({
  json: confirm({ body: x.json.body, statusCode: x.json.statusCode }),
  pairedItem: { item: i },
}));
